function igAvisoText(){const td=todayISO();const lim=todayISO(new Date(Date.now()+14*864e5));const ev=IGR.a.filter(x=>x.dt>=td&&x.dt<=lim).sort((a,b)=>(a.dt+(a.hr||'')).localeCompare(b.dt+(b.hr||'')));
  const bd=IGR.m.filter(m=>m.nasc&&m.sit!=='a').filter(m=>{for(let i=0;i<=7;i++){if(todayISO(new Date(Date.now()+i*864e5)).slice(5)===m.nasc.slice(5))return true}return false}).sort((a,b)=>a.nasc.slice(5).localeCompare(b.nasc.slice(5)));
  const o=[t('ig_a_hd'),''];if(ev.length){o.push(t('ig_a_ev'));ev.forEach(x=>o.push('· '+igDw(x.dt)+(x.hr?' '+x.hr:'')+' — '+x.t+(x.loc?' ('+x.loc+')':'')));o.push('')}
  if(bd.length){o.push(t('ig_a_bd'));bd.forEach(m=>o.push('· '+igName(m.n)+' — '+igDM(m.nasc)));o.push('')}
  o.push(t('ig_a_end'),igSig());return o.join('\n')}
