/* ---- Cópia de segurança dos dados da igreja (usada pelo "Baixar tudo" do Perfil) ---- */
function igWait(){igStart();const t0=Date.now();return new Promise(ok=>{const f=()=>{if(Object.keys(IG_COL).every(k=>IGR.ok[k])||Date.now()-t0>10000)ok();else setTimeout(f,150)};f()})}
async function igBackup(){if(!igOk())return null;await igWait();const o={};for(const k in IG_COL)o[IG_COL[k]]=IGR[k].map(x=>Object.assign({},x));return o}
async function igRestore(o){if(!igOk()||!o||typeof o!=='object')return 0;await igWait();const C=igCols();let n=0;
  for(const k in IG_COL){const arr=o[IG_COL[k]];if(!Array.isArray(arr))continue;
    for(const x of arr){if(!x||typeof x.id!=='string'||!x.id||x.id.includes('/'))continue;const cur=IGR[k].find(y=>y.id===x.id);
      if(cur&&(+x.upd||0)<=(+cur.upd||0))continue;const d=Object.assign({},x);delete d.id;C[k].doc(x.id).set(d).catch(()=>{});n++}}
  return n}

;({igrHtml,igHomeHtml,igBackup,igRestore})
